{
  "version": "schemaxis.readiness/1",
  "routes": {
    "schemaxis.gnuplot/1": {
      "guide": "docs/gnuplot.md",
      "context": {
        "purpose": "Plot named numeric CSV series with units, explicit ranges and optional symmetric y uncertainty or an asserted asymmetric lower/upper range envelope.",
        "assumptions": "Finite increasing x data, matching units, bounded local CSV; fixed margins and typography.",
        "constraints": "2\u20132048 rows, 2\u201312 columns, 1\u20134 series; linear/log10, no missing data or clipping, ASCII labels. A bounds envelope: linear axes, one series, lower < upper, lower <= y <= upper, each row at least 24 pixels tall.",
        "inspection": "Inspect raw native plot.svg/plot.png, captured.csv and trusted plot.gp. plot-summary.json records independent host inspection and is not native readback.",
        "recovery": "INVALID_PLOT_RANGE: increasing separated positive log ranges. INVALID_LOG_DATA: positive values and uncertainty endpoints. PLOT_UNIT_MISMATCH: declare matching column/axis units. INVALID_PLOT_DATA: rectangular numeric cells/header. INTERPRETER_NOT_FOUND: configure Gnuplot. INVALID_PLOT_BOUNDS: use distinct columns with lower < upper and lower <= y <= upper; not together with error. PLOT_BOUNDS_UNSUPPORTED: linear axes and one series only. PLOT_BAND_UNVERIFIABLE: widen, flatten or rescale the envelope so its pixels can be verified."
      },
      "examples": [
        {
          "id": "baseline",
          "reference": "examples/schemaxis/gnuplot-calibration.json"
        },
        {
          "id": "variant",
          "reference": "examples/schemaxis/gnuplot-calibration-variant.json"
        },
        {
          "id": "logarithmic",
          "reference": "examples/schemaxis/gnuplot-logarithmic.json"
        },
        {
          "id": "logarithmic-variant",
          "reference": "examples/schemaxis/gnuplot-logarithmic-variant.json"
        },
        {
          "id": "invalid-range",
          "reference": "examples/schemaxis/gnuplot-range-invalid.json",
          "expect": "invalid",
          "fault": "INVALID_PLOT_RANGE",
          "schemaValid": true
        },
        {
          "id": "band",
          "reference": "examples/schemaxis/gnuplot-band.json"
        },
        {
          "id": "band-variant",
          "reference": "examples/schemaxis/gnuplot-band-variant.json"
        },
        {
          "id": "band-symmetric-invalid",
          "reference": "examples/schemaxis/gnuplot-band-symmetric-invalid.json",
