        "tools/qualify_gnuplot.py"
      ],
      "profiles": {
        "workflow": {
          "scope": "Run plotting jobs as isolated common workflow operations with independently verified outputs.",
          "references": [
            "docs/gnuplot.md",
            "tools/qualify_gnuplot.py"
          ]
        },
        "composition": {
          "scope": "Shared document references, pure expressions and finite studies resolve before native plotting.",
          "references": [
            "docs/gnuplot.md",
            "tools/qualify_gnuplot.py"
          ]
        }
      },
      "development": {
        "api": [
          "https://gnuplot.sourceforge.net/docs_6.0/loc8145.html",
          "https://gnuplot.sourceforge.net/docs_6.0/loc9562.html",
          "https://gnuplot.sourceforge.net/docs_6.0/loc13689.html",
          "https://gnuplot.sourceforge.net/docs_6.0/loc22928.html",
          "https://gnuplot.sourceforge.net/docs_6.0/loc22106.html"
        ],
        "lifecycle": {
          "timeout": "One total deadline covers native version/render and final verification; native CPU 60s, address space 512MiB, file 16MiB.",
          "cancellation": "Shared process-group cancellation terminates the owned native process; check cancellation before publication.",
          "logs": "Authored/effective plans, source capture/digest, trusted script, stage input hashes, launcher, command submissions/stdout/stderr, raw SVG/PNG and host inspection summary are retained.",
          "verification": "Independent standard-library SVG geometry/labels and decoded PNG dimensions/series pixels use the captured CSV and declared axis transforms. Exact native/evidence/publication membership and trusted script/input bindings are checked. A bounds envelope is read back as exactly the expected native polygon vertices in order, fill colour and 0.2 opacity, a legend swatch at the native key-sample size and offset and the central curve, with every polygon in the document required to be one of those two in the envelope group, and with independent PNG interior probes at every row and segment midpoint, plus exterior probes where observable with at least one across the plot."
        },
